cd /tmp/e2e && cat > e2e.mjs <<'EOF'
import { chromium } from 'playwright';

const URL = 'http://localhost:4173/';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 1000 } });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`${m.type()}: ${m.text()}`); });
page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));

await page.goto(URL, { waitUntil: 'networkidle' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'networkidle' });

const rects = () => page.$$eval('.dash-widget', (els) =>
  els.map((el) => {
    const r = el.getBoundingClientRect();
    return { id: el.querySelector('h2')?.textContent, x: r.x, y: r.y, w: r.width, h: r.height };
  }));
const overlapPairs = (rs) => {
  const bad = [];
  for (let i = 0; i < rs.length; i++) for (let j = i + 1; j < rs.length; j++) {
    const a = rs[i], b = rs[j];
    if (a.x < b.x + b.w - 1 && b.x < a.x + a.w - 1 && a.y < b.y + b.h - 1 && b.y < a.y + a.h - 1) bad.push(`${a.id} x ${b.id}`);
  }
  return bad;
};

const report = {};
report.count = (await rects()).length;
report.initialOverlaps = overlapPairs(await rects());
await page.screenshot({ path: '/tmp/e2e/01-initial.png', fullPage: true });

// 1) drag "Каналы" (bottom-left) to the top-right corner
const grip = page.locator('.dash-widget', { hasText: 'Каналы' }).first().locator('.dash-widget__grip');
const gb = await grip.boundingBox();
await page.mouse.move(gb.x + 20, gb.y + 10);
await page.mouse.down();
for (let s = 1; s <= 20; s++) await page.mouse.move(gb.x + 20 + (900 - gb.x) * s / 20, gb.y + 10 + (-560) * s / 20, { steps: 1 });
const midDrag = await rects();
report.duringDragOverlaps = overlapPairs(midDrag);
await page.screenshot({ path: '/tmp/e2e/02-dragging.png', fullPage: true });
await page.mouse.up();
await page.waitForTimeout(300);
const afterDrag = await rects();
report.afterDragOverlaps = overlapPairs(afterDrag);
report.channelsPos = afterDrag.find((r) => r.id === 'Каналы');
await page.screenshot({ path: '/tmp/e2e/03-after-drag.png', fullPage: true });

// 2) resize "Структура выручки" wider via handle
const seg = page.locator('.dash-widget', { hasText: 'Структура выручки' }).first();
const before = await seg.boundingBox();
const handle = seg.locator('.dash-widget__resize');
const hb = await handle.boundingBox();
await page.mouse.move(hb.x + 8, hb.y + 8);
await page.mouse.down();
await page.mouse.move(hb.x + 8 + 120, hb.y + 8 + 40, { steps: 10 });
await page.mouse.up();
await page.waitForTimeout(300);
const after = await seg.boundingBox();
report.resize = { beforeW: Math.round(before.width), afterW: Math.round(after.width), beforeH: Math.round(before.height), afterH: Math.round(after.height) };
report.afterResizeOverlaps = overlapPairs(await rects());

// 3) keyboard: focus "Заметка"? use revenue widget grip, ArrowRight x2
const kg = page.locator('.dash-widget', { hasText: 'Выручка' }).first().locator('.dash-widget__grip');
const kb0 = await page.locator('.dash-widget', { hasText: 'Выручка' }).first().boundingBox();
await kg.focus();
await page.keyboard.press('ArrowRight');
await page.keyboard.press('ArrowRight');
await page.waitForTimeout(300);
const kb1 = await page.locator('.dash-widget', { hasText: 'Выручка' }).first().boundingBox();
report.keyboardMove = { dx: Math.round(kb1.x - kb0.x) };
await page.keyboard.press('Shift+ArrowRight');
await page.waitForTimeout(300);
const kb2 = await page.locator('.dash-widget', { hasText: 'Выручка' }).first().boundingBox();
report.keyboardResize = { dw: Math.round(kb2.width - kb1.width) };
report.afterKeyOverlaps = overlapPairs(await rects());

// 4) table toggle on dynamics
const dyn = page.locator('.dash-widget', { hasText: 'Динамика выручки' }).first();
await dyn.getByRole('button', { name: 'Таблица' }).click();
report.tableRows = await dyn.locator('tbody tr').count();
await dyn.getByRole('button', { name: 'График' }).click();

// 5) hover tooltip on line chart and on channel bars
const dynSvg = dyn.locator('svg[role="img"]');
const dsb = await dynSvg.boundingBox();
await page.mouse.move(dsb.x + dsb.width * 0.5, dsb.y + dsb.height * 0.5);
await page.waitForTimeout(100);
report.lineTooltip = await dyn.locator('.viz-tooltip').count();
report.lineTooltipText = (await dyn.locator('.viz-tooltip').textContent().catch(() => null));
await page.screenshot({ path: '/tmp/e2e/04-tooltip.png', fullPage: true });

// 6) persistence: reload and compare positions
const beforeReload = await rects();
await page.reload({ waitUntil: 'networkidle' });
const afterReload = await rects();
report.persisted = JSON.stringify(beforeReload.map(({ id, x, y, w, h }) => [id, Math.round(x), Math.round(y), Math.round(w), Math.round(h)])) ===
  JSON.stringify(afterReload.map(({ id, x, y, w, h }) => [id, Math.round(x), Math.round(y), Math.round(w), Math.round(h)]));
report.afterReloadOverlaps = overlapPairs(afterReload);

// 7) reset
await page.getByRole('button', { name: 'Сбросить раскладку' }).click();
await page.waitForTimeout(300);
report.afterResetOverlaps = overlapPairs(await rects());
report.afterResetFirstWidget = (await rects())[0];

report.errors = errors;
console.log(JSON.stringify(report, null, 2));
await browser.close();
EOF
